insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:google-project-management','catalog_item','google-project-management','Google Project Management Professional Certificate by Google / Coursera. Type: course. Level: beginner. Skills: Project management, Agile & Scrum, Business communication. Relevant roles: Project Coordinator / Junior Project Manager, Operations Associate / Analyst, Product Operations / Junior Product Manager. Estimated time: 60 hours. Cost: $59/month subscription. Certificate: completion (recognition: high). 6 courses incl. capstone. Recognized for PMI CAPM education hours. Can be audited free (no certificate). Keywords: PMBOK, agile, backlog, english, gantt, kanban, milestones, presentation, product owner, project charter, project management, project planning, reporting to management, retrospective, risk management, scheduling, scope, scrum, scrum master, sprint, stakeholder communication, stakeholder management, standup, storytelling, user stories, writing.','{"type": "course", "cost_type": "subscription", "price": 59, "currency": "USD", "certificate_type": "completion", "recognition": "high", "est_hours": 60, "level": "beginner", "skills": ["project-management", "agile-scrum", "communication"], "roles": ["project-coordinator", "operations-associate", "product-operations"], "url_verified": true, "last_verified_at": null, "subscription_group": "coursera-plus"}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:google-project-management-audit','catalog_item','google-project-management-audit','Google Project Management (audit mode) by Google / Coursera. Type: course. Level: beginner. Skills: Project management, Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Operations Associate / Analyst, Product Operations / Junior Product Manager. Estimated time: 55 hours. Cost: Free to audit; certificate about $59. Certificate: none (recognition: low). Audit availability varies by course; graded items and certificate require payment. Keywords: PMBOK, agile, backlog, gantt, kanban, milestones, product owner, project charter, project management, project planning, retrospective, risk management, scheduling, scope, scrum, scrum master, sprint, stakeholder management, standup, user stories.','{"type": "course", "cost_type": "free_audit", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 55, "level": "beginner", "skills": ["project-management", "agile-scrum"], "roles": ["project-coordinator", "operations-associate", "product-operations"], "url_verified": true, "last_verified_at": "2026-11-01", "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:psm-1','catalog_item','psm-1','Professional Scrum Master I (PSM I) – exam by Scrum.org. Type: cert exam. Level: beginner. Skills: Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Product Operations / Junior Product Manager, Operations Associate / Analyst, QA Tester / Junior QA Engineer, Business Analyst. Estimated time: 1 hours. Cost: $200. Certificate: official exam (recognition: high). 80 questions, 60 minutes, 85% to pass. Lifetime certification. Prep: Scrum Guide + Scrum Open. Keywords: agile, backlog, kanban, product owner, retrospective, scrum, scrum master, sprint, standup, user stories.','{"type": "cert_exam", "cost_type": "one_time", "price": 200, "currency": "USD", "certificate_type": "official_exam", "recognition": "high", "est_hours": 1, "level": "beginner", "skills": ["agile-scrum"], "roles": ["project-coordinator", "product-operations", "operations-associate", "qa-tester", "business-analyst"], "url_verified": true, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:scrum-guide','catalog_item','scrum-guide','The Scrum Guide (read twice) by Scrum.org / scrumguides.org. Type: course. Level: beginner. Skills: Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Product Operations / Junior Product Manager. Estimated time: 3 hours. Cost: Free. Certificate: none (recognition: low). Official, short, free. Core prep for PSM I / PSPO I. Keywords: agile, backlog, kanban, product owner, retrospective, scrum, scrum master, sprint, standup, user stories.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 3, "level": "beginner", "skills": ["agile-scrum"], "roles": ["project-coordinator", "product-operations"], "url_verified": true, "last_verified_at": "2026-11-01", "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:scrum-open','catalog_item','scrum-open','Scrum Open practice assessment by Scrum.org. Type: course. Level: beginner. Skills: Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Product Operations / Junior Product Manager. Estimated time: 3 hours. Cost: Free. Certificate: none (recognition: low). UNVERIFIED: this link could not be reached in the 2026-11-01 check and no replacement is confirmed yet; show ''needs check''. Free practice test; repeat until 100% before PSM I. Keywords: agile, backlog, kanban, product owner, retrospective, scrum, scrum master, sprint, standup, user stories.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 3, "level": "beginner", "skills": ["agile-scrum"], "roles": ["project-coordinator", "product-operations"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:pspo-1','catalog_item','pspo-1','Professional Scrum Product Owner I (PSPO I) – exam by Scrum.org. Type: cert exam. Level: beginner. Skills: Agile & Scrum, Product management. Relevant roles: Product Operations / Junior Product Manager. Estimated time: 1 hours. Cost: $200. Certificate: official exam (recognition: high). Price commonly $200; confirm on Scrum.org. Keywords: agile, backlog, discovery, kanban, mvp, prd, prioritization, product management, product owner, product strategy, retrospective, roadmap, scrum, scrum master, sprint, standup, user research, user stories.','{"type": "cert_exam", "cost_type": "one_time", "price": 200, "currency": "USD", "certificate_type": "official_exam", "recognition": "high", "est_hours": 1, "level": "beginner", "skills": ["agile-scrum", "product-management"], "roles": ["product-operations"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:capm','catalog_item','capm','Certified Associate in Project Management (CAPM) – exam by PMI. Type: cert exam. Level: intermediate. Skills: Project management. Relevant roles: Project Coordinator / Junior Project Manager. Estimated time: 60 hours. Cost: $300. Certificate: official exam (recognition: high). $300 non-member / $225 member (membership $139 + $10). Requires 23 contact hours of PM education (Google PM certificate counts). Valid 3 years. Keywords: PMBOK, gantt, milestones, project charter, project management, project planning, risk management, scheduling, scope, stakeholder management.','{"type": "cert_exam", "cost_type": "one_time", "price": 300, "currency": "USD", "certificate_type": "official_exam", "recognition": "high", "est_hours": 60, "level": "intermediate", "skills": ["project-management"], "roles": ["project-coordinator"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:jira-fundamentals','catalog_item','jira-fundamentals','Jira Fundamentals learning path by Atlassian University. Type: course. Level: beginner. Skills: Jira & Confluence, Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Product Operations / Junior Product Manager, Technical Operations / Support Specialist, Operations Associate / Analyst, QA Tester / Junior QA Engineer, Business Analyst. Estimated time: 1.5 hours. Cost: Free. Certificate: completion (recognition: low). ~90 minutes, assessment-backed badge. Pair with a real Jira board in a free workspace. Needs check: the catalog URL no longer resolves to this learning path. Keywords: agile, atlassian, backlog, boards, confluence, epics, jira, jira service management, kanban, product owner, retrospective, scrum, scrum master, sprint, standup, tickets, user stories.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "completion", "recognition": "low", "est_hours": 1.5, "level": "beginner", "skills": ["jira", "agile-scrum"], "roles": ["project-coordinator", "product-operations", "technical-operations", "operations-associate", "qa-tester", "business-analyst"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:lean-six-sigma-white-belt','catalog_item','lean-six-sigma-white-belt','Lean Six Sigma White Belt by GoLeanSixSigma. Type: course. Level: beginner. Skills: Process improvement. Relevant roles: Operations Associate / Analyst, Supply Chain / Logistics Analyst, Business Analyst. Estimated time: 2 hours. Cost: Free. Certificate: completion (recognition: low). Free with certificate (recertify every 2 years). Keywords: bottleneck, continuous improvement, efficiency, kpi, lean, process improvement, root cause, six sigma, sop, workflow.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "completion", "recognition": "low", "est_hours": 2, "level": "beginner", "skills": ["process-improvement"], "roles": ["operations-associate", "supply-chain-analyst", "business-analyst"], "url_verified": true, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
