insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:coursera-agile-with-atlassian-jira','catalog_item','coursera-agile-with-atlassian-jira','Agile with Atlassian Jira by Atlassian (Coursera). Type: course. Level: beginner. Skills: Jira & Confluence, Agile & Scrum. Relevant roles: Project Coordinator / Junior Project Manager, Product Operations / Junior Product Manager, QA Tester / Junior QA Engineer, Technical Operations / Support Specialist. Estimated time: 10 hours. Cost: $59/month subscription. Certificate: completion (recognition: low). ''1 week at 10 hours a week''; No prior experience required; prepares for Atlassian University badge APB-330. Page says ''Enroll now'' and ''Included with Coursera Plus'', no price or audit option listed. Coursera shows ''Enroll for free'' but the certificate needs the paid Certificate experience; the page does not state a price (Coursera FAQ wording varies by course). Treat cost as unspecified until a human confirms. Stated as 1 week at 10 hours a week. Included with Coursera Plus per the item page; no price is stated there, so the shared Coursera Plus price of the existing items is used. Free audit not confirmed: do not treat as free. Needs check: price. Keywords: agile, atlassian, backlog, boards, confluence, epics, jira, jira service management, kanban, product owner, retrospective, scrum, scrum master, sprint, standup, tickets, user stories.','{"type": "course", "cost_type": "subscription", "price": 59, "currency": "USD", "certificate_type": "completion", "recognition": "low", "est_hours": 10, "level": "beginner", "skills": ["jira", "agile-scrum"], "roles": ["project-coordinator", "product-operations", "qa-tester", "technical-operations"], "url_verified": true, "last_verified_at": "2026-11-01", "subscription_group": "coursera-plus"}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
