insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:servicenow-welcome-to-servicenow','catalog_item','servicenow-welcome-to-servicenow','Welcome to ServiceNow (Now Learning) by ServiceNow University. Type: course. Level: unspecified. Skills: Ticketing & helpdesk tools. Relevant roles: Technical Support Specialist, IT Support / Junior System Administrator. Estimated time: 3 hours. Cost: Free. Certificate: none (recognition: low). Not opened. Search listing: course page says ''This course is retired''; ServiceNow Administration Fundamentals pricing conflicting in community posts. Do not add until re-checked. Reported retired. Price not stated on the page; stored as free (0) but unverified. Hours are a Skillstack estimate (the page states no duration). Needs check: url and price. No url yet (the page could not be opened). Keywords: escalation, freshdesk, helpdesk, jira service management, knowledge base, macros, queue, service desk, servicenow, ticketing, tier 1, tier 2, zendesk.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 3, "level": "unspecified", "skills": ["ticketing-helpdesk"], "roles": ["technical-support-specialist", "it-sysadmin"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:futurelearn-understanding-gdpr','catalog_item','futurelearn-understanding-gdpr','Understanding the GDPR (FutureLearn) by FutureLearn. Type: course. Level: unspecified. Skills: Data privacy & confidentiality. Relevant roles: People Operations / Recruiting Coordinator, IT Support / Junior System Administrator. Estimated time: 12 hours. Cost: Free. Certificate: none (recognition: low). URL withheld: https://www.futurelearn.com/courses/general-data-protection-regulation returned HTTP 403. Search listing: 4 weeks at about 3 h/week, free access period; unverified. Price not stated on the page; stored as free (0) but unverified. Hours are a Skillstack estimate (4 weeks at about 3 h/week comes from a search listing only). Needs check: url and price. No url yet (the page could not be opened). Keywords: access control, confidentiality, consent, data protection, data retention, data subject request, gdpr, information security policy, nda, pii, privacy.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 12, "level": "unspecified", "skills": ["data-privacy-confidentiality"], "roles": ["people-operations", "it-sysadmin"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('item:google-digital-garage-digital-marketing','catalog_item','google-digital-garage-digital-marketing','Fundamentals of digital marketing (Google Digital Garage) by Google. Type: course. Level: unspecified. Skills: Digital marketing. Relevant roles: Marketing Coordinator, Growth / Digital Marketing (junior). Estimated time: 20 hours. Cost: Free. Certificate: none (recognition: low). URL withheld: https://learndigital.withgoogle.com/digitalgarage/course/digital-marketing returned a 301 redirect to https://grow.google/ (so the old course URL is gone). Search listings say the course moved to Skillshop and certificate validation ended: unverified. Old URL redirects to grow.google; may be moved. Price not stated on the page; stored as free (0) but unverified. Hours are a Skillstack estimate (the page states no duration). Needs check: url and price. No url yet (the page could not be opened). Keywords: content marketing, digital marketing, email marketing, google ads, growth, performance marketing, sem, seo, social media.','{"type": "course", "cost_type": "free", "price": 0, "currency": "USD", "certificate_type": "none", "recognition": "low", "est_hours": 20, "level": "unspecified", "skills": ["digital-marketing"], "roles": ["marketing-coordinator", "growth-marketing"], "url_verified": false, "last_verified_at": null, "subscription_group": null}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:operations-associate','role','operations-associate','Role: Operations Associate / Analyst. Also known as: Operations Associate, Operations Analyst, Business Operations Associate, Operations Coordinator, Ops Specialist, Business Operations Analyst, Operations Manager (junior). Keeps the business running: processes, reporting, vendors, internal tools, and cross-team coordination. Strong fit for ex-military officers with planning and management experience. Key skills (importance): Operations management (5/5), Process improvement (5/5), Excel & spreadsheets (5/5), SQL (4/5), Data analysis (4/5), Project management (4/5), Business communication (4/5), BI & data visualization (3/5), Jira & Confluence (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), No-code & AI automation (3/5), People leadership (3/5), Technical writing & documentation (2/5). Job-description keywords: operations, processes, kpis, reporting, cross-functional, stakeholders, excel, sql, dashboards, vendor, efficiency, sop, ownership, fast-paced.','{"skills": ["operations-management", "process-improvement", "excel", "sql", "data-analysis", "project-management", "bi-visualization", "communication", "jira", "ai-literacy", "interviewing", "no-code-automation", "people-leadership", "technical-writing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:technical-operations','role','technical-operations','Role: Technical Operations / Support Specialist. Also known as: Technical Operations Specialist, Tech Ops, Technical Support Specialist, Support Engineer (junior), Production Support, NOC Operator, Application Support. Monitors and supports a live product: incidents, troubleshooting, APIs, logs, and escalation to R&D. Key skills (importance): Incident & service management (5/5), APIs & integrations (5/5), IT support & troubleshooting (5/5), SQL (4/5), Jira & Confluence (4/5), Business communication (4/5), Cloud fundamentals (3/5), Process improvement (3/5), Interview readiness (3/5), Linux & command line (3/5), Technical writing & documentation (3/5), Python basics (2/5), Networking basics (2/5). Job-description keywords: troubleshooting, incidents, escalation, sla, api, logs, monitoring, sql, jira, linux, on-call, shifts, technical, customer-facing.','{"skills": ["incident-management", "apis", "it-support", "sql", "cloud", "jira", "python", "communication", "process-improvement", "interviewing", "linux", "networking", "technical-writing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:product-operations','role','product-operations','Role: Product Operations / Junior Product Manager. Also known as: Product Operations, Product Ops, Junior Product Manager, Associate Product Manager, APM, Product Analyst, Product Specialist. Connects product, data and teams: roadmaps, requirements, analytics, tooling and launch processes. Key skills (importance): Product management (5/5), Business communication (5/5), Product analytics (4/5), Agile & Scrum (4/5), Jira & Confluence (4/5), Data analysis (4/5), SQL (3/5), UX basics (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), Business analysis (3/5), Technical writing & documentation (3/5). Job-description keywords: product, roadmap, requirements, prd, user stories, prioritization, analytics, stakeholders, launch, agile, jira, data-driven, customer insights.','{"skills": ["product-management", "product-analytics", "agile-scrum", "jira", "sql", "data-analysis", "ux-basics", "communication", "ai-literacy", "interviewing", "business-analysis", "technical-writing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:project-coordinator','role','project-coordinator','Role: Project Coordinator / Junior Project Manager. Also known as: Project Coordinator, Junior Project Manager, Project Manager, Program Coordinator, PMO Analyst, Delivery Coordinator. Plans and tracks projects: schedules, risks, resources and stakeholder updates. Key skills (importance): Project management (5/5), Business communication (5/5), Jira & Confluence (4/5), Excel & spreadsheets (4/5), Agile & Scrum (3/5), Process improvement (3/5), Operations management (3/5), Interview readiness (3/5), People leadership (3/5), Technical writing & documentation (3/5). Job-description keywords: project management, timelines, milestones, risk, stakeholders, gantt, scrum, agile, pmo, budget, status reports, coordination, capm, pmp.','{"skills": ["project-management", "agile-scrum", "jira", "excel", "communication", "process-improvement", "operations-management", "interviewing", "people-leadership", "technical-writing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:data-analyst','role','data-analyst','Role: Junior Data / BI Analyst. Also known as: Data Analyst, Junior Data Analyst, BI Analyst, Reporting Analyst, Business Intelligence Analyst. Turns data into decisions: SQL, dashboards, metrics and business insights. Key skills (importance): SQL (5/5), Data analysis (5/5), BI & data visualization (5/5), Excel & spreadsheets (5/5), Business communication (4/5), Statistics (4/5), Python basics (3/5), Product analytics (3/5), Interview readiness (3/5). Job-description keywords: sql, power bi, tableau, dashboards, excel, python, kpis, data, insights, reporting, etl, analysis, statistics, bigquery.','{"skills": ["sql", "data-analysis", "bi-visualization", "excel", "python", "product-analytics", "communication", "interviewing", "statistics"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:ai-deployment-specialist','role','ai-deployment-specialist','Role: AI Implementation / Deployment Specialist. Also known as: Deployment Strategist, Implementation Specialist, Solutions Specialist, AI Implementation Manager, Forward Deployed (junior), Solutions Consultant, Customer Solutions. Deploys AI products at customers: understands their processes, configures agents, manages rollout and adoption. Key skills (importance): AI agents & automation (5/5), AI literacy & prompting (5/5), Business communication (5/5), APIs & integrations (4/5), Process improvement (4/5), Project management (4/5), Customer success (4/5), Cloud fundamentals (3/5), Interview readiness (3/5), No-code & AI automation (3/5), Pre-sales & solution demos (3/5), SQL (2/5). Job-description keywords: ai, llm, agents, deployment, implementation, customer, workflows, integration, api, consulting, rollout, adoption, stakeholders, enterprise.','{"skills": ["ai-agents", "ai-literacy", "apis", "process-improvement", "project-management", "customer-success", "communication", "cloud", "sql", "interviewing", "no-code-automation", "presales-demos"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
