insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:growth-marketing','role','growth-marketing','Role: Growth / Digital Marketing (junior). Also known as: Growth Marketing, Digital Marketing Specialist, Performance Marketing, Marketing Associate, Content Marketing, Marketing Operations. Drives acquisition and engagement through campaigns, content, analytics and experiments. Key skills (importance): Digital marketing (5/5), Web analytics (5/5), Data analysis (4/5), AI literacy & prompting (4/5), Business communication (4/5), Excel & spreadsheets (3/5), Product analytics (3/5), CRM tools (3/5), Interview readiness (3/5), Statistics (2/5), No-code & AI automation (2/5). Job-description keywords: growth, campaigns, google ads, seo, content, email, analytics, ga4, conversion, a/b testing, funnels, cac, roi, social media.','{"skills": ["digital-marketing", "web-analytics", "data-analysis", "excel", "product-analytics", "crm", "ai-literacy", "communication", "interviewing", "statistics", "no-code-automation"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:qa-tester','role','qa-tester','Role: QA Tester / Junior QA Engineer. Also known as: QA Tester, Manual QA, QA Analyst, Junior QA Engineer, Software Tester, Test Engineer. Makes sure the product works before customers see it: test plans, test cases, bug reports and regression. Key skills (importance): Software testing & QA (5/5), APIs & integrations (4/5), Jira & Confluence (4/5), SQL (3/5), Technical writing & documentation (3/5), Agile & Scrum (3/5), Business communication (3/5), Interview readiness (3/5), Git & GitHub (2/5). Job-description keywords: qa, testing, test cases, bugs, regression, jira, api testing, postman, sql, agile, automation, istqb.','{"skills": ["software-testing", "apis", "sql", "jira", "git", "technical-writing", "agile-scrum", "communication", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:soc-analyst','role','soc-analyst','Role: Junior Cybersecurity / SOC Analyst. Also known as: SOC Analyst, Security Analyst, Cybersecurity Analyst, Tier 1 SOC, Security Operations. Monitors alerts, investigates incidents and escalates threats in a security operations center. Key skills (importance): Cybersecurity fundamentals (5/5), Incident & service management (5/5), Networking basics (4/5), Linux & command line (4/5), IT support & troubleshooting (3/5), Technical writing & documentation (3/5), Interview readiness (3/5), Python basics (2/5). Job-description keywords: soc, siem, alerts, incident response, threats, phishing, network, linux, security+, logs, shifts, escalation.','{"skills": ["cybersecurity", "networking", "linux", "incident-management", "it-support", "python", "technical-writing", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:it-sysadmin','role','it-sysadmin','Role: IT Support / Junior System Administrator. Also known as: IT Support, Helpdesk, IT Specialist, Junior Sysadmin, System Administrator, IT Technician. Keeps people and systems running: devices, accounts, networks, cloud tools and user support. Key skills (importance): IT support & troubleshooting (5/5), Linux & command line (4/5), Networking basics (4/5), Cloud fundamentals (4/5), Incident & service management (4/5), Cybersecurity fundamentals (3/5), Business communication (3/5), Interview readiness (3/5). Job-description keywords: it support, helpdesk, windows, linux, active directory, office 365, google workspace, network, tickets, hardware, sla.','{"skills": ["it-support", "linux", "networking", "cloud", "cybersecurity", "incident-management", "communication", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:business-analyst','role','business-analyst','Role: Business Analyst. Also known as: Business Analyst, Junior BA, Systems Analyst, Process Analyst, Requirements Analyst. Translates business needs into clear requirements and process changes for product and tech teams. Key skills (importance): Business analysis (5/5), Business communication (5/5), Process improvement (4/5), Excel & spreadsheets (4/5), Technical writing & documentation (4/5), SQL (3/5), Data analysis (3/5), Agile & Scrum (3/5), BI & data visualization (3/5), Interview readiness (3/5). Job-description keywords: requirements, stakeholders, process mapping, bpmn, user stories, use cases, gap analysis, sql, documentation, agile, ecba.','{"skills": ["business-analysis", "process-improvement", "sql", "excel", "data-analysis", "agile-scrum", "bi-visualization", "technical-writing", "communication", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:revenue-operations','role','revenue-operations','Role: Revenue Operations / Sales Ops. Also known as: RevOps, Revenue Operations, Sales Operations, Marketing Operations, GTM Operations, CRM Admin. Runs the systems and data behind sales and marketing: CRM, pipeline reporting, routing and forecasting. Key skills (importance): Revenue operations (5/5), CRM tools (5/5), Excel & spreadsheets (4/5), Data analysis (4/5), No-code & AI automation (4/5), SQL (3/5), BI & data visualization (3/5), Business communication (3/5), Interview readiness (3/5). Job-description keywords: revops, salesforce, hubspot, crm, pipeline, forecasting, dashboards, lead routing, automation, gtm, attribution, data hygiene.','{"skills": ["revops", "crm", "excel", "data-analysis", "no-code-automation", "sql", "bi-visualization", "communication", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:people-operations','role','people-operations','Role: People Operations / Recruiting Coordinator. Also known as: People Operations, HR Coordinator, Recruiting Coordinator, Talent Acquisition Coordinator, HR Generalist (junior), Talent Sourcer. Hiring and the employee lifecycle: recruiting pipelines, onboarding, HR processes and people data. Key skills (importance): Recruiting & HR (5/5), Business communication (5/5), Excel & spreadsheets (3/5), Process improvement (3/5), People leadership (3/5), AI literacy & prompting (3/5), Interview readiness (3/5). Job-description keywords: recruiting, sourcing, interviews, onboarding, hris, employee experience, people, hr, talent, ats, linkedin recruiter.','{"skills": ["recruiting-hr", "communication", "excel", "process-improvement", "people-leadership", "ai-literacy", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:supply-chain-analyst','role','supply-chain-analyst','Role: Supply Chain / Logistics Analyst. Also known as: Supply Chain Analyst, Logistics Coordinator, Procurement Analyst, Demand Planner, Operations Planner, Purchasing Coordinator. Plans and optimizes the flow of goods: inventory, suppliers, demand planning and logistics data. Key skills (importance): Supply chain & logistics (5/5), Excel & spreadsheets (5/5), Data analysis (4/5), Operations management (4/5), Process improvement (4/5), SQL (3/5), BI & data visualization (3/5), Interview readiness (3/5), ERP systems (3/5). Job-description keywords: supply chain, logistics, inventory, procurement, suppliers, demand planning, erp, sap, excel, kpis, forecasting.','{"skills": ["supply-chain", "excel", "data-analysis", "operations-management", "process-improvement", "sql", "bi-visualization", "interviewing", "erp-systems"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
