insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:automation-specialist','role','automation-specialist','Role: No-code / AI Automation Specialist. Also known as: Automation Specialist, Workflow Automation, AI Automation Specialist, Business Systems Analyst, Internal Tools. Builds workflows that connect tools and AI to remove manual work: Zapier, Make, n8n, Power Automate, LLMs. Key skills (importance): No-code & AI automation (5/5), AI agents & automation (4/5), APIs & integrations (4/5), Process improvement (4/5), AI literacy & prompting (4/5), Technical writing & documentation (3/5), Business communication (3/5), Interview readiness (3/5). Job-description keywords: automation, zapier, make, n8n, power automate, workflows, integrations, api, ai, llm, internal tools, efficiency.','{"skills": ["no-code-automation", "ai-agents", "apis", "process-improvement", "ai-literacy", "technical-writing", "communication", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:customer-support-specialist','role','customer-support-specialist','Role: Customer Support Specialist. Also known as: Customer Service Representative, Customer Support Representative, Customer Care Representative, Client Services Representative, Customer Service Specialist, Customer Service Agent, Call Center Representative, Member Services Representative, Support Agent. Answers customers by chat, email and phone, resolves or escalates issues in a ticketing tool, and keeps records. A common entry point into customer success, technical support and operations. Key skills (importance): Customer service (5/5), Business communication (5/5), Ticketing & helpdesk tools (4/5), CRM tools (4/5), Data privacy & confidentiality (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), Incident & service management (2/5), Sales & business development (2/5), Data analysis (2/5). Job-description keywords: customer service, tickets, zendesk, crm, sla, csat, escalation, live chat, inbound calls, de-escalation, knowledge base, first response time.','{"skills": ["customer-service", "communication", "ticketing-helpdesk", "crm", "data-privacy-confidentiality", "incident-management", "sales", "data-analysis", "ai-literacy", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:technical-support-specialist','role','technical-support-specialist','Role: Technical Support Specialist. Also known as: Help Desk Analyst, Help Desk Technician, IT Support Specialist, Desktop Support Technician, Technical Support Engineer (Tier 1/2), Application Support Analyst. First and second line support for software or devices: reproduce issues, troubleshoot by following runbooks, log tickets and escalate to engineering. Bridges customer service and IT operations. Key skills (importance): IT support & troubleshooting (5/5), Ticketing & helpdesk tools (5/5), Customer service (4/5), Business communication (4/5), Windows & Microsoft 365 admin (3/5), Networking basics (3/5), Jira & Confluence (3/5), CRM tools (3/5), Incident & service management (3/5), Technical writing & documentation (3/5), Interview readiness (3/5), Linux & command line (2/5), SQL (2/5), APIs & integrations (2/5). Job-description keywords: troubleshooting, help desk, ticketing, tier 1, tier 2, remote support, windows, active directory, knowledge base, sla, escalation, customer-facing, servicenow, jira service management.','{"skills": ["it-support", "ticketing-helpdesk", "customer-service", "communication", "windows-m365-admin", "networking", "jira", "crm", "incident-management", "technical-writing", "linux", "sql", "apis", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:administrative-coordinator','role','administrative-coordinator','Role: Administrative Coordinator. Also known as: Administrative Assistant, Administrative Coordinator, Office Administrator, Administrative Specialist, Office Assistant, Staff Assistant, Administrative Support Assistant, Department Secretary. Keeps an office or team running: calendars, meetings, travel, documents, supplies, simple bookkeeping and correspondence. Often the first step toward operations, HR or project coordination. Key skills (importance): Office administration (5/5), Business communication (5/5), Excel & spreadsheets (4/5), Data privacy & confidentiality (3/5), Work management tools (3/5), Interview readiness (3/5), Bookkeeping & accounting (2/5), Project management (2/5), AI literacy & prompting (2/5), Technical writing & documentation (2/5). Job-description keywords: scheduling, calendar management, travel arrangements, microsoft office, correspondence, filing, minutes, front desk, expense reports, data entry, confidentiality.','{"skills": ["office-administration", "communication", "excel", "data-privacy-confidentiality", "work-management-tools", "bookkeeping-accounting", "project-management", "ai-literacy", "technical-writing", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:bookkeeping-clerk','role','bookkeeping-clerk','Role: Bookkeeper / Accounts Payable & Receivable Clerk. Also known as: Bookkeeper, Accounting Clerk, Accounts Payable Clerk, Accounts Payable Specialist, Accounts Receivable Clerk, Accounting Associate, Billing Clerk. Records transactions, issues invoices, reconciles accounts and supports month-end in accounting software. Entry point for finance-operations and junior financial analyst work. Key skills (importance): Bookkeeping & accounting (5/5), Excel & spreadsheets (5/5), Finance & accounting basics (4/5), ERP systems (3/5), Business communication (3/5), Interview readiness (3/5), Data privacy & confidentiality (2/5), Data analysis (2/5), Process improvement (2/5). Job-description keywords: accounts payable, accounts receivable, reconciliation, general ledger, invoicing, quickbooks, xero, month-end, journal entries, payroll, sap.','{"skills": ["bookkeeping-accounting", "excel", "finance-basics", "erp-systems", "communication", "data-privacy-confidentiality", "data-analysis", "process-improvement", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:procurement-specialist','role','procurement-specialist','Role: Procurement Specialist / Buyer. Also known as: Buyer, Purchasing Agent, Procurement Specialist, Purchasing Administrator, Contract Administrator, Procurement Coordinator. Finds and evaluates suppliers, issues requests for quotes and purchase orders, negotiates terms and tracks orders in an ERP. Common route into supply chain and operations. Key skills (importance): Procurement & sourcing (5/5), Negotiation (4/5), Supply chain & logistics (4/5), ERP systems (4/5), Excel & spreadsheets (4/5), Business communication (4/5), Finance & accounting basics (3/5), Demand & inventory planning (3/5), Data analysis (3/5), Interview readiness (3/5), Operations management (2/5). Job-description keywords: procurement, purchasing, sourcing, rfq, rfp, purchase orders, suppliers, vendor management, contracts, negotiation, erp, sap, cost savings.','{"skills": ["procurement-sourcing", "negotiation", "supply-chain", "erp-systems", "excel", "communication", "finance-basics", "demand-inventory-planning", "data-analysis", "operations-management", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:marketing-coordinator','role','marketing-coordinator','Role: Marketing Coordinator. Also known as: Marketing Coordinator, Marketing Specialist, Marketing Assistant, Content Marketing Specialist, Social Media Coordinator, Market Research Analyst, Communications Specialist, Content Strategist. Plans and runs campaigns and content, tracks results, and gathers customer and competitor information. Broader and more content-oriented than the existing growth-marketing role. Key skills (importance): Digital marketing (5/5), Content & social media marketing (5/5), Business communication (5/5), Market research (4/5), Web analytics (4/5), Data analysis (3/5), CRM tools (3/5), Excel & spreadsheets (3/5), Work management tools (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), BI & data visualization (2/5), Statistics (2/5). Job-description keywords: campaigns, content, social media, seo, email marketing, hubspot, google analytics, brand, copywriting, market research, editorial calendar, wordpress.','{"skills": ["digital-marketing", "content-social-marketing", "communication", "market-research", "web-analytics", "data-analysis", "crm", "excel", "work-management-tools", "ai-literacy", "bi-visualization", "statistics", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:technical-writer','role','technical-writer','Role: Technical Writer. Also known as: Technical Writer, Documentation Specialist, Documentation Writer, Content Developer, Knowledge Base Writer, Technical Communicator, Requirements Writer. Writes and maintains product, process and API documentation, help-centre articles and release notes, working with engineers and support. Natural fit for people with strong writing and structured thinking. Key skills (importance): Technical writing & documentation (5/5), Business communication (5/5), Work management tools (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), UX basics (2/5), APIs & integrations (2/5), Git & GitHub (2/5), Project management (2/5), Jira & Confluence (2/5). Job-description keywords: documentation, technical writing, api documentation, knowledge base, user guides, release notes, markdown, confluence, dita, style guide, docs-as-code.','{"skills": ["technical-writing", "communication", "work-management-tools", "ai-literacy", "ux-basics", "apis", "git", "project-management", "jira", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
insert into rag_documents (id,kind,ref_id,content,metadata) values ('role:learning-development-coordinator','role','learning-development-coordinator','Role: Learning & Development Coordinator. Also known as: Training Coordinator, Training Specialist, Learning and Development Specialist, Learning and Development Coordinator, Corporate Trainer, Enablement Coordinator. Plans and delivers employee or customer training: needs assessment, materials, scheduling, delivery (in person and virtual) and evaluation. Fit for people with teaching, coaching or military instruction backgrounds. Key skills (importance): Training & facilitation (5/5), Business communication (5/5), Project management (3/5), Recruiting & HR (3/5), Office administration (3/5), Technical writing & documentation (3/5), People leadership (3/5), Excel & spreadsheets (3/5), AI literacy & prompting (3/5), Interview readiness (3/5), Data analysis (2/5), Work management tools (2/5). Job-description keywords: training, onboarding, facilitation, curriculum, lms, e-learning, needs assessment, instructional design, workshops, learning objectives, enablement.','{"skills": ["training-facilitation", "communication", "project-management", "recruiting-hr", "office-administration", "technical-writing", "people-leadership", "excel", "ai-literacy", "data-analysis", "work-management-tools", "interviewing"]}'::jsonb) on conflict (id) do update set content=excluded.content, metadata=excluded.metadata;
